const initSqlJs = require('sql.js');
const fs = require('fs');

async function main() {
  const SQL = await initSqlJs();
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);

  // Search for user by partial email
  const users = db.exec(\"SELECT user_id, email, name FROM users WHERE email LIKE '%maya%' OR name LIKE '%maya%' OR name LIKE '%Maya%' OR name LIKE '%chen%' OR name LIKE '%Chen%'\");
  console.log('Users matching maya/chen:', JSON.stringify(users));

  // Look for order ORD-5B048F
  const orders = db.exec(\"SELECT * FROM orders WHERE order_id LIKE '%5B048F%' OR order_id LIKE '%5b048f%'\");
  console.log('Orders matching 5B048F:', JSON.stringify(orders));

  // Look for item ITEM-63F395
  const items = db.exec(\"SELECT * FROM order_items WHERE oi_id LIKE '%63F395%' OR oi_id LIKE '%63f395%'\");
  console.log('Items matching 63F395:', JSON.stringify(items));

  // Look for warranty matching item
  const warr = db.exec(\"SELECT * FROM warranties WHERE oi_id LIKE '%63F395%' OR oi_id LIKE '%63f395%'\");
  console.log('Warranties matching 63F395:', JSON.stringify(warr));
}
main().catch(console.error);
"

